using Microsoft.EntityFrameworkCore;using EnterpriseDocumentIntelligence.BuildingBlocks.Domain;
namespace EnterpriseDocumentIntelligence.BuildingBlocks.Infrastructure;
public sealed class DocumentDbContext(DbContextOptions<DocumentDbContext> options):DbContext(options){public DbSet<Document> Documents=>Set<Document>();public DbSet<DocumentVersion> DocumentVersions=>Set<DocumentVersion>();public DbSet<Chunk> Chunks=>Set<Chunk>();public DbSet<DocumentAcl> DocumentAcls=>Set<DocumentAcl>();public DbSet<ProcessingJob> ProcessingJobs=>Set<ProcessingJob>();public DbSet<AuditEvent> AuditEvents=>Set<AuditEvent>();protected override void OnModelCreating(ModelBuilder b){b.Entity<Document>().HasIndex(x=>new{x.TenantId,x.Name});b.Entity<DocumentVersion>().HasIndex(x=>new{x.DocumentId,x.VersionNumber}).IsUnique();b.Entity<Chunk>().HasIndex(x=>new{x.DocumentVersionId,x.ChunkNumber}).IsUnique();b.Entity<DocumentAcl>().HasIndex(x=>new{x.DocumentId,x.PrincipalId,x.Permission}).IsUnique();b.Entity<AuditEvent>().HasIndex(x=>new{x.TenantId,x.CreatedAt});b.Entity<Document>().HasMany(x=>x.Versions).WithOne(x=>x.Document).HasForeignKey(x=>x.DocumentId);b.Entity<Document>().HasMany(x=>x.Acls).WithOne().HasForeignKey(x=>x.DocumentId);}}